export default function prepareReplyMessageIds({ events }) {
  if (!Array.isArray(events)) throw new Error("Gmail must supply a message event array.");
  const messageIds = events.map((event) => event?.messageId);
  if (
    messageIds.some((id) => typeof id !== "string" || id.trim() === "") ||
    new Set(messageIds).size !== messageIds.length
  )
    throw new Error("Every incoming Gmail message needs one unique message ID.");
  return { messageIds };
}

