export function validateReplyMessage(message) {
  for (const key of ["messageId", "threadId", "from"])
    if (typeof message?.[key] !== "string" || message[key].trim() === "")
      throw new Error("Incoming Gmail message is missing " + key + ".");
  if (
    typeof message.subject !== "string" ||
    typeof message.body !== "string" ||
    /[\r\n]/.test(message.from + message.subject)
  )
    throw new Error("Gmail subject, sender and body fields are invalid.");
  return {
    messageId: message.messageId,
    threadId: message.threadId,
    from: message.from,
    subject: message.subject,
    body: message.body,
  };
}

export default function collectReplyMessages({
  messageIds,
  previousState,
  messageId,
  threadId,
  from,
  subject,
  body,
}) {
  let state;
  if (previousState === null) {
    if ([messageId, threadId, from, subject, body].some((value) => value !== null))
      throw new Error("Unexpected message before collection starts.");
    state = { index: 0, messages: [] };
  } else {
    if (
      !Number.isSafeInteger(previousState.index) ||
      previousState.index < 0 ||
      previousState.index >= messageIds.length ||
      !Array.isArray(previousState.messages) ||
      previousState.messages.length !== previousState.index ||
      messageId !== messageIds[previousState.index]
    )
      throw new Error("The Gmail message does not match this read frame.");
    state = {
      index: previousState.index + 1,
      messages: [
        ...previousState.messages,
        validateReplyMessage({ messageId, threadId, from, subject, body }),
      ],
    };
  }
  return {
    state,
    messageId: messageIds[state.index] ?? "unused-completed-frame",
    more: state.index < messageIds.length,
  };
}

