export function validateReplyDecision(completion) {
  if (
    !completion ||
    typeof completion !== "object" ||
    Array.isArray(completion) ||
    typeof completion.needsReply !== "boolean"
  )
    throw new Error("The assessment must contain a boolean needsReply.");
  return completion.needsReply;
}

export default function collectReplyDecisions({ messages, previousState, completion }) {
  let state;
  if (previousState === null) {
    if (completion !== null)
      throw new Error("Unexpected reply assessment before processing starts.");
    state = { index: 0, decisions: [] };
  } else {
    if (
      !Number.isSafeInteger(previousState.index) ||
      previousState.index < 0 ||
      previousState.index >= messages.length ||
      !Array.isArray(previousState.decisions) ||
      previousState.decisions.length !== previousState.index
    )
      throw new Error("Invalid Gmail assessment state.");
    const decision = {
      messageId: messages[previousState.index].messageId,
      needsReply: validateReplyDecision(completion),
    };
    state = { index: previousState.index + 1, decisions: [...previousState.decisions, decision] };
  }
  const more = state.index < messages.length,
    selected = more ? [] : messages.filter((_message, index) => state.decisions[index].needsReply);
  return {
    state,
    selected,
    subject: messages[state.index]?.subject ?? "",
    body: messages[state.index]?.body ?? "",
    more,
  };
}

