export function prepareReplyDraft(message, completion) {
  if (typeof completion !== "string" || completion.trim() === "")
    throw new Error("The reply model returned no draft text.");
  const escape = (text) =>
    text
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#39;");
  return {
    sourceMessageId: message.messageId,
    threadId: message.threadId,
    to: message.from,
    subject: "Re: " + message.subject,
    body: escape(completion).replace(/\r\n|\r|\n/g, "<br />\n"),
  };
}

export default function collectReplyDrafts({ messages, previousState, completion }) {
  let state;
  if (previousState === null) {
    if (completion !== null) throw new Error("Unexpected reply before draft generation starts.");
    state = { index: 0, drafts: [] };
  } else {
    if (
      !Number.isSafeInteger(previousState.index) ||
      previousState.index < 0 ||
      previousState.index >= messages.length ||
      !Array.isArray(previousState.drafts) ||
      previousState.drafts.length !== previousState.index
    )
      throw new Error("Invalid Gmail draft generation state.");
    state = {
      index: previousState.index + 1,
      drafts: [
        ...previousState.drafts,
        prepareReplyDraft(messages[previousState.index], completion),
      ],
    };
  }
  return {
    state,
    subject: messages[state.index]?.subject ?? "",
    body: messages[state.index]?.body ?? "",
    more: state.index < messages.length,
  };
}

