export default function collectReplyReceipts({ plans, previousState, draftId, returnedThreadId }) {
  let state;
  if (previousState === null) {
    if (draftId !== null || returnedThreadId !== null)
      throw new Error("Unexpected draft receipt before writing starts.");
    state = { index: 0, drafts: [] };
  } else {
    if (
      !Number.isSafeInteger(previousState.index) ||
      previousState.index < 0 ||
      previousState.index >= plans.length ||
      !Array.isArray(previousState.drafts) ||
      previousState.drafts.length !== previousState.index
    )
      throw new Error("Invalid draft receipt state.");
    const plan = plans[previousState.index];
    if (
      typeof draftId !== "string" ||
      draftId.trim() === "" ||
      (returnedThreadId !== null && returnedThreadId !== plan.threadId)
    )
      throw new Error(
        "Gmail did not confirm a draft in the requested conversation; check Drafts before repeating.",
      );
    state = {
      index: previousState.index + 1,
      drafts: [
        ...previousState.drafts,
        { sourceMessageId: plan.sourceMessageId, threadId: plan.threadId, draftId },
      ],
    };
  }
  const plan = plans[state.index];
  return {
    state,
    to: plan?.to ?? "",
    subject: plan?.subject ?? "",
    body: plan?.body ?? "",
    threadId: plan?.threadId ?? "",
    more: state.index < plans.length,
    count: state.index,
  };
}
